declare function require(id: string): any;
const fs = require('fs');

export function isAllowed(role: string): boolean {
  const allowed = fs.readFileSync('allowedRoles.txt', 'utf8').trim().split(',').map((s: string) => s.trim());
  return allowed.includes(role);
}

